/bin/zsh -lc "cat > main.go <<'EOF'
package main

import (
	\"crypto/rand\"
	\"math/big\"
	\"os\"
	\"text/template\"
)

func main() {
	value, err := rand.Int(rand.Reader, big.NewInt(1<<31))
	if err "'!= nil {
		panic(err)
	}

	const greeting = `{{.Greeting}} {{.Value}}`
	tmpl := template.Must(template.New("greeting").Parse(greeting))
	data := struct {
		Greeting string
		Value    *big.Int
	}{Greeting: "Hello World", Value: value}

	if err := tmpl.Execute(os.Stdout, data); err != nil {
		panic(err)
	}
}
EOF
gofmt -w main.go'

